import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"漸","description":"东坡易传 - 漸","frontmatter":{"title":"漸","description":"东坡易传 - 漸"},"headers":[],"relativePath":"zh/classics/dongpo/054.md","filePath":"zh/classics/dongpo/054.md"}'),o={name:"zh/classics/dongpo/054.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="漸" tabindex="-1">漸 <a class="header-anchor" href="#漸" aria-label="Permalink to “漸”">​</a></h1><p>“漸”：女歸吉，利貞。</p><p>《彖》曰：“漸”，之進也。“女歸吉”也，進得位、往有功也。進以正，可以正邦也；其位剛得中也。止而“巽”，動不窮也。</p><p>此文轉以次相釋也。“漸”之中有進者，則“女歸”之“吉”也，而利於正。正者孰謂？謂“得位”而“有功”、“可以正邦”者也。其“得位”者何也？“剛中”者也。由此觀之，女則二與四；所歸則五也。 “止而‘巽’”，有所觀望而後進者，故不窮。</p><p>象曰：山上有木，“漸”；君子以居賢德善俗。</p><p>雲上於天，天所不能居，故君子不以居德；木生於山，山能居之，山以有木爲高，故君子以是居德業、善風俗。</p><p>初六：鴻漸於幹，小子厲；有言，無咎。象曰：“小子”之“厲”，義無咎也。</p><p>“鴻”，陽鳥而水居，在水則以得陸爲安，在陸則以得水爲樂者也。故六爻雖有陰陽之異，而皆取於鴻也。初六，鴻之在水者也，遠則無應，近則遇二，以陰適陰，故曰“鴻漸於幹”。“幹”，水涯也。兩陰不能相容，故爲“小子”之所“厲”，以至於“有言”。雖然其所適非志於利也，則未至於六三之兇，“無咎”可也。</p><p>六二：鴻漸於磐，飲食衎衎，吉。象曰：“飲食衎衎”，不素飽也。</p><p>六二，鴻之在水者也。近則遇三，遠則遇五，無適而不得其欲①，故擇其尤可恃者從之。二之從三也，雖近而難信；其從五也，雖遠而可恃。二陽皆陸也，在陸而尤可恃以安者，磐也，九五之謂“磐”。六二知五之可恃，不漸於三而漸於五，則食且樂如是。“衎衎”，樂也。“素飽”，徒飽也。夫飲食何爲若昌樂也？豈非以五之足恃而不徒飽歟？苟爲徒飽而已，則雖三可從；夫苟從三，則飲食未終而憂繼之矣。</p><p>【校注】 ① 不得其欲：《蘇氏易傳》作“不得其遇”，誤。</p><p>九三：鴻漸於陸，夫徵不復。婦孕不育，兇；利禦寇。象曰：“夫徵不復”，離羣醜也；“婦孕不育”，失其道也。利用“禦寇”，順相保也。</p><p>九三，鴻之在陸者也；而上九非其應，故曰“鴻漸於陸”。無應於上而近於四，見四之可欲，則離類絕朋而趨之，故曰“夫徵不復”。六二之從我，非正也，將視我而進退者也。上之所爲，下必有甚者，九三適四而不反①，則難以令於二矣。故曰：“婦孕不育，兇。”四，順於五者；而三寇之，言“禦寇”之利，以明三之不利也。</p><p>【校注】 ① 九三適四而不反：《蘇氏易傳》作“九二適四而不反”，誤。</p><p>六四：鴻漸於木，或得其桷，無咎。象曰：“或得其桷”，順以“巽”也。</p><p>六四，鴻之在水者也。近於五而非其應，故曰“鴻漸於木”。木生於陸，而非鴻之所安也；鴻之爲物也，足不能握，其“漸於木”而“無咎”，蓋得其大而有容如桷者焉，九五之謂也。“或”者，幸而得之之辭也。無應而從非其配，非“巽”順，何以相保乎？</p><p>九五：鴻漸於陵，婦三歲不孕，終莫之勝，吉。象曰：“終莫之勝，吉”，得所原也。</p><p>九五，鴻之在陸者也；進而遇上九。上九，陵也；陵者，陸之又高者也；進而之陵，動乎無嫌，故六二之爲“婦”也，“三歲不孕”而終莫之勝。夫以陸之陵，以爲不得其願矣，而婦爲之貞如此，則願孰大焉。故曰：“進以正，可以正邦也。”不求之人而求之身，雖服天下可也。</p><p>上九：鴻漸於陸，其羽可用爲儀，吉。象曰：“其羽可用爲儀，吉”，不可亂也。</p><p>上九，鴻之在陸者也。上無所適，而三非其應，故曰“鴻漸於逵”。“漸”有三陽，其二爲陰之所溷，非其有應，則近而慕之。惟上九不然：夫無累於物，則其進退之際，雍容而可觀矣。</p>',20)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
